Convert this Express app from callbacks to async/await across both files, preserving the error-handling middleware contract:

```js
// routes/users.js
router.get('/:id', (req, res, next) => {
  db.getUser(req.params.id, (err, user) => {
    if (err) return next(err);
    if (!user) return res.status(404).end();
    audit.log('read', user.id, (err2) => {
      if (err2) return next(err2);
      res.json(user);
    });
  });
});

// lib/db.js
exports.getUser = (id, cb) => pool.query('SELECT * FROM users WHERE id=$1', [id], (e, r) => cb(e, r && r.rows[0]));
```

